package com.lolfm.composition;
import com.lolfm.champion.ChampionRoleKey;import java.util.*;
public final class CompositionDeficiencyEvaluator{public Map<CompositionDeficiency,DeficiencyEvaluation>evaluate(TeamCompositionCoverage c){EnumMap<CompositionDeficiency,DeficiencyEvaluation>out=new EnumMap<>(CompositionDeficiency.class);CompositionDeficiencyPolicy.definitions().forEach((d,x)->out.put(d,evaluate(x,c)));return Map.copyOf(out);}public DeficiencyEvaluation evaluate(DeficiencyDefinition d,TeamCompositionCoverage c){EnumMap<CompositionCapability,Double>e=new EnumMap<>(CompositionCapability.class);boolean present;double severity;List<ChampionRoleKey>contributors=new ArrayList<>();if(d.deficiency()==CompositionDeficiency.DAMAGE_CHANNEL_SKEW){var damage=c.damageChannels();double dominant=Math.max(damage.physicalShare(),damage.magicShare());present=damage.shareApplicable()&&dominant>=CompositionDeficiencyPolicy.DAMAGE_SKEW;severity=present?clamp((dominant-.80)/.20):0;}else if(d.deficiency()==CompositionDeficiency.NO_SIDE_LANE_ANSWER){double side=c.capability(CompositionCapability.SIDE_LANE_PRESSURE).coverage(),wave=c.capability(CompositionCapability.WAVE_CLEAR).coverage();e.put(CompositionCapability.SIDE_LANE_PRESSURE,side);e.put(CompositionCapability.WAVE_CLEAR,wave);present=side<CompositionDeficiencyPolicy.SIDE_LANE&&wave<CompositionDeficiencyPolicy.WAVE_CLEAR;severity=present?(shortfall(side,CompositionDeficiencyPolicy.SIDE_LANE)+shortfall(wave,CompositionDeficiencyPolicy.WAVE_CLEAR))/2:0;contributors.add(primary(c,CompositionCapability.SIDE_LANE_PRESSURE));contributors.add(primary(c,CompositionCapability.WAVE_CLEAR));}else{var entry=d.thresholds().entrySet().iterator().next();double value=c.capability(entry.getKey()).coverage();e.put(entry.getKey(),value);present=value<entry.getValue();severity=present?shortfall(value,entry.getValue()):0;contributors.add(primary(c,entry.getKey()));}return new DeficiencyEvaluation(d.deficiency(),present,zero(severity),e,c.damageChannels(),contributors,d.explanationKey());}private ChampionRoleKey primary(TeamCompositionCoverage c,CompositionCapability x){return c.capability(x).contributors().getFirst().championRoleKey();}private static double shortfall(double v,double t){return clamp((t-v)/t);}private static double clamp(double v){return Math.max(0,Math.min(1,v));}private static double zero(double v){return v==0?0.0:v;}}
